1	// Package contractsentinel strictjson: fixed-field recognition shared by the
2	// audit submission and the stored report.
3	package contractsentinel
4	
5	import "encoding/json"
6	
7	// fixedShape describes the fixed fields of one JSON object: keys lists the
8	// agreed member spellings kept at this level, objects names members whose
9	// values are themselves objects with their own fixed shape, and arrays names
10	// members whose values are arrays of such objects. Members not named anywhere
11	// in the shape are extension data.
12	//
13	// Both entry points that decode user-supplied JSON — the audit submission and
14	// the stored report archive — are decoded through a fixedShape, so the
15	// recognition convention exists exactly once: a member denotes a fixed field
16	// only when its JSON-decoded name matches the agreed spelling byte for byte.
17	// encoding/json otherwise falls back to case-insensitive field matching, so
18	// an extension member such as "StAtus" would silently decode into the status
19	// field and could override — or launder — the conclusion carried by the
20	// formal "status" member, depending on where the extension member appears.
21	// Case variants, whitespace-padded names and unknown members never reach the
22	// decoder: they can neither override a formal value nor substitute for a
23	// missing, mistyped or unsupported one, whatever JSON type the extension
24	// value has. Names are compared after JSON string decoding, so a fixed name
25	// written with escapes still denotes that field.
26	type fixedShape struct {
27		keys    []string
28		objects map[string]fixedShape
29		arrays  map[string]fixedShape
30	}
31	
32	// strictFixedJSON rewrites data to the fixed fields of shape, at this level
