18	// 本文件在真实命令行进程边界上回归保护 audit 的“外部检查结果导入”：
19	// 用户给出满足 ABI/字节码要求的产物、带版本规则和 checks 记录后，
20	// 结论必须带着原产物哈希与规则版本进入已保存报告，并能用返回的报告标识
21	// 原样读回；任何一条哈希或版本不匹配的记录都必须整份拒绝提交。
22	
23	// cliWireArtifact/cliWireRule/cliWireCheck 是提交 JSON 在测试侧的镜像，
24	// 字段与 contractsentinel 的线框格式一致，但独立定义，避免测试依赖内部类型。
25	type cliWireArtifact struct {
26		Name     string `json:"name"`
27		ABI      string `json:"abi"`
28		Bytecode string `json:"bytecode"`
29		Source   string `json:"source"`
30	}
31	
32	type cliWireRule struct {
33		ID          string `json:"id"`
34		Kind        string `json:"kind"`
35		Severity    string `json:"severity"`
36		Invariant   string `json:"invariant"`
37		RequiresABI bool   `json:"requiresABI"`
38		Version     string `json:"version"`
39	}
