49	type cliWireInput struct {
50		Artifact   cliWireArtifact `json:"artifact"`
51		Rules      []cliWireRule   `json:"rules"`
52		Invariants map[string]bool `json:"invariants,omitempty"`
53		Checks     []cliWireCheck  `json:"checks,omitempty"`
54	}
