57	
58	// 缺陷说明刻意包含中文、换行和前后空格，任何修剪或模板替换都会被抓到。
59	const defectNote = "  反例：攻击者可在 withdraw 中重入\n  第二行证据  "
60	
61	// mixedCheckArtifact 是规则要求齐备的产物：非空 ABI 与字节码。
62	func mixedCheckArtifact() cliWireArtifact {
63		return cliWireArtifact{
64			Name:     "Vault",
65			ABI:      `[{"name":"withdraw","type":"function"}]`,
66			Bytecode: "0x60806040",
67			Source:   "contract Vault {\n}\n",
68		}
69	}
70	
71	func mixedCheckRules() []cliWireRule {
72		return []cliWireRule{
73			{ID: "rule-pass", Kind: "static", Severity: "low", Invariant: "inv-pass", Version: "1.4.0"},
74			{ID: "rule-defect", Kind: "static", Severity: "high", Invariant: "inv-defect", Version: "2.0.1"},
75			{ID: "rule-tool", Kind: "static", Severity: "medium", Invariant: "inv-tool", RequiresABI: true, Version: "3.0.0"},
76			{ID: "rule-timeout", Kind: "symbolic", Severity: "critical", Invariant: "inv-timeout", Version: "0.9.2"},
77			{ID: "rule-unchecked", Kind: "static", Severity: "info", Invariant: "inv-unchecked", Version: "5.0.0"},
78		}
79	}
80	
81	// mixedCheckInput 构造一份同时含通过、缺陷、工具缺失、超时的合法提交；
82	// 第五条规则没有任何记录，应为未检查。
83	func mixedCheckInput(hash string) cliWireInput {
84		return cliWireInput{
