510		stdout, stderr, code := runCLIAudit(t, bin, input, store)
511		if code != 0 {
512			t.Fatalf("legal import must succeed, stderr=%s", stderr)
513		}
514		report := decodeReport(t, stdout)
515		if len(report.ReportID) != 64 {
516			t.Fatalf("report id length = %d, want 64", len(report.ReportID))
