1	package contractsentinel
2	
3	import (
4		"errors"
5		"fmt"
6		"strings"
7		"testing"
8	)
9	
10	// 本文件锁定 audit 提交侧规则定义五个文本成员 id、kind、severity、
11	// invariant、version 的类型规则。它们在 wireRule 中都是 Go 字符串，
12	// json.Unmarshal 会把正式成员的 null 静默解码成零值 ""：一条 id 与 version
13	// 合法的规则，即使 kind、severity 或 invariant 写成 null，也可能通过全部
14	// 业务检查并生成报告，空掉的定义与用户明确提交空字符串得到的规则定义、
15	// 报告标识和缺陷绑定完全相同，格式错误被洗成了合法提交。
16	//
17	// 修正后，五个正式成员（约定拼写，含 Unicode 转义写法）一旦写出，其值就
18	// 必须是 JSON 字符串；null、布尔值、数字、对象、数组都使整份提交失败
19	// （errInvalid），与该规则是否被检查、是否产生缺陷无关，其他规则和检查
20	// 记录合法也不能挽救。错误点名 rules 数组中从零开始的位置与出错成员并
21	// 说明必须为字符串，规则有合法非空 id 时同时点名该 id；id 自身非法时凭
22	// 位置定位。省略成员与显式空字符串仍按既有默认值与业务要求判断；
23	// Kind、带前后空格的名称及未知成员只是扩展信息，其中的 null 不触发错误，
24	// 合法字符串也不能补上缺失字段或挽救非法正式字段。
25	
26	// ruleTextSubmission 拼装一份 audit 提交：rulesJSON 是 rules 数组的完整
27	// JSON（含方括号），extra 是追加的顶层片段（invariants、checks 等）。
28	func ruleTextSubmission(rulesJSON string, extra ...string) string {
29		sections := append([]string{`"artifact":` + strictArtifactJSON, `"rules":` + rulesJSON}, extra...)
30		return strictDoc(sections...)
31	}
32	
33	// ruleObject 用给出的原始成员片段拼出一个规则对象。
34	func ruleObject(members ...string) string {
35		return "{" + strings.Join(members, ",") + "}"
36	}
37	
38	// expectInvalidRuleText 断言整份提交被拒绝：errInvalid、错误点名 rules
39	// 数组位置、字段与字符串要求；id 参数为""时错误不得携带规则标识。
40	func expectInvalidRuleText(t *testing.T, in, position, id, field string) {
41		t.Helper()
42		artifact, rules, invariants, checks, err := ParseAuditInput([]byte(in))
43		if err == nil {
44			t.Fatalf("a non-string formal %s must reject the whole submission\ninput: %s", field, in)
45		}
46		var ei errInvalid
47		if !errors.As(err, &ei) {
48			t.Fatalf("a rule text type error is a submission format error (errInvalid), got %T: %v", err, err)
49		}
50		msg := err.Error()
51		if !strings.Contains(msg, position) {
52			t.Fatalf("error must name the rules-array position %q: %v", position, err)
53		}
54		if !strings.Contains(msg, field+" must be a string") {
55			t.Fatalf("error must state %s must be a string: %v", field, err)
56		}
57		if id != "" {
58			if !strings.Contains(msg, "(rule "+id+")") {
59				t.Fatalf("error must name the legal rule id %q: %v", id, err)
60			}
61		} else if strings.Contains(msg, "(rule ") {
62			t.Fatalf("an illegal id must leave the rule locatable by position alone: %v", err)
63		}
64		// 这是规则定义的提交格式错误，不得记成任何检查结论。
65		for _, marker := range []string{StatusDefect, StatusToolMissing, StatusTimeout} {
66			if strings.Contains(msg, marker) {
67				t.Fatalf("a format error must not be reported as the conclusion %q: %v", marker, err)
68			}
69		}
70		if artifact != (Artifact{}) || rules != nil || invariants != nil || checks != nil {
71			t.Fatalf("rejection must return no partial data: %+v %+v %+v %+v", artifact, rules, invariants, checks)
72		}
73	}
74	
75	// --- 核心场景：id 与 version 合法，kind/severity/invariant 为 null 也必须拒绝 ---
76	
77	func TestParseAuditNullRuleDefinitionTextRejected(t *testing.T) {
78		for _, field := range []string{"kind", "severity", "invariant"} {
79			t.Run(field, func(t *testing.T) {
80				// 没有检查记录：规则只会依据 invariant 布尔值得出结论，与类型关无关。
81				rule := ruleObject(`"id":"r1"`, `"`+field+`":null`,
82					`"requiresABI":false`, `"version":"1.0.0"`)
83				in := ruleTextSubmission("["+rule+"]", `"invariants":{"inv":true}`)
84				expectInvalidRuleText(t, in, "rules[0]", "r1", field)
85			})
86		}
87	}
88	
89	// --- 五个文本成员写成 null 都整份拒绝；id 自身非法时只凭位置定位 ---
90	
91	func TestParseAuditNullRuleTextFieldsRejected(t *testing.T) {
92		for _, field := range submissionRuleTextFields {
93			t.Run(field, func(t *testing.T) {
94				// id 自身为 null 时没有可点名的合法规则标识，其余字段仍可定位规则。
95				id := "r1"
96				if field == "id" {
97					id = ""
98				}
99				expectInvalidRuleText(t, ruleTextSubmission("["+ruleTextWithValue(field, "null")+"]"),
100					"rules[0]", id, field)
101			})
102		}
103	}
104	
105	// --- 布尔值、数字、对象、数组同样整份拒绝，不能被当成空字符串 ---
106	
107	// ruleTextWithValue 构造一条五个文本成员齐全的规则，仅把 field 的值换成
108	// 原始片段 val（其余成员保持合法字符串）。
109	func ruleTextWithValue(field, val string) string {
110		values := map[string]string{
111			"id": `"r1"`, "kind": `"static"`, "severity": `"high"`,
112			"invariant": `"inv"`, "version": `"1.0.0"`,
113		}
114		values[field] = val
115		members := make([]string, 0, len(submissionRuleTextFields))
116		for _, f := range submissionRuleTextFields {
117			members = append(members, `"`+f+`":`+values[f])
118		}
119		return ruleObject(members...)
120	}
121	
122	func TestParseAuditNonStringRuleTextFieldsRejected(t *testing.T) {
123		values := []string{"true", "false", "0", "123", "{}", "[]", `["x"]`}
124		for _, field := range submissionRuleTextFields {
125			for _, val := range values {
126				t.Run(field+"/"+val, func(t *testing.T) {
127					in := ruleTextSubmission("[" + ruleTextWithValue(field, val) + "]")
128					artifact, _, _, _, err := ParseAuditInput([]byte(in))
129					if err == nil {
130						t.Fatalf("%s=%s must reject the whole submission", field, val)
131					}
132					if !strings.Contains(err.Error(), "rules[0]") ||
133						!strings.Contains(err.Error(), field+" must be a string") {
134						t.Fatalf("error must name the position, field and string requirement: %v", err)
135					}
136					if artifact != (Artifact{}) {
137						t.Fatalf("rejection must return no partial artifact: %+v", artifact)
138					}
139				})
140			}
141		}
142	}
143	
144	// --- 位置与点名：出错规则按数组下标定位，规则内按正式字段顺序报第一个 ---
145	
146	func TestParseAuditRuleTextErrorNamesPositionAndID(t *testing.T) {
147		// 第二条规则非法：错误必须点名 rules[1] 与它的合法 id，而不是第一条。
148		rules := "[" +
149			ruleObject(`"id":"r0"`, `"kind":"static"`, `"severity":"low"`, `"invariant":"i0"`, `"version":"1"`) + "," +
150			ruleObject(`"id":"r2"`, `"kind":null`, `"severity":"high"`, `"invariant":"i2"`, `"version":"2"`) +
151			"]"
152		expectInvalidRuleText(t, ruleTextSubmission(rules), "rules[1]", "r2", "kind")
153	
154		// 同一规则内多个字段非法且书写顺序任意：按 id、kind、severity、
155		// invariant、version 的正式顺序报第一个，这里是 kind 而不是 severity。
156		rule := `{"severity":null,"invariant":null,"id":"r9","kind":null,"version":"9"}`
157		expectInvalidRuleText(t, ruleTextSubmission("["+rule+"]"), "rules[0]", "r9", "kind")
158	
159		// 多条规则非法：报数组中最靠前的一条。
160		twoBad := "[" +
161			ruleObject(`"id":"a"`, `"version":"1"`, `"severity":null`) + "," +
162			ruleObject(`"id":"b"`, `"version":"2"`, `"kind":null`) +
163			"]"
164		_, _, _, _, err := ParseAuditInput([]byte(ruleTextSubmission(twoBad)))
165		if err == nil || !strings.Contains(err.Error(), "rules[0]") ||
166			!strings.Contains(err.Error(), "severity must be a string") {
167			t.Fatalf("the first offending rule must be reported by its array index: %v", err)
168		}
169	}
170	
171	// --- 与检查记录无关：该规则有合法检查结论，或其他规则、检查记录全部合法，
172	// 都不能使提交成功；格式错误不被记成缺陷、工具缺失或超时 ---
173	
174	func TestParseAuditNullRuleTextRejectedRegardlessOfChecks(t *testing.T) {
175		hash := ArtifactHash(strictTestArtifact())
176	
177		// 非法规则本身带着一条完全合法的“发现缺陷”检查记录：仍在构建报告前拒绝。
178		badRule := ruleObject(`"id":"r1"`, `"kind":null`, `"severity":"high"`,
179			`"invariant":"inv"`, `"version":"1.0.0"`)
180		defectCheck := fmt.Sprintf(
181			`{"artifactHash":%q,"ruleId":"r1","version":"1.0.0","status":"发现缺陷","note":"ce"}`, hash)
182		in := ruleTextSubmission("["+badRule+"]", `"checks":[`+defectCheck+`]`)
183		expectInvalidRuleText(t, in, "rules[0]", "r1", "kind")
184	
185		// 另一条规则及其“通过”检查记录完全合法，也不能挽救第二条规则的 null。
186		goodRule := ruleObject(`"id":"r1"`, `"kind":"static"`, `"severity":"low"`,
187			`"invariant":"i1"`, `"version":"1.0.0"`)
188		otherBad := ruleObject(`"id":"r2"`, `"kind":"static"`, `"severity":null`,
189			`"invariant":"i2"`, `"version":"2.0.0"`)
190		passCheck := fmt.Sprintf(
191			`{"artifactHash":%q,"ruleId":"r1","version":"1.0.0","status":"通过"}`, hash)
192		in = ruleTextSubmission("["+goodRule+","+otherBad+"]", `"checks":[`+passCheck+`]`)
193		expectInvalidRuleText(t, in, "rules[1]", "r2", "severity")
194	}
195	
196	// --- 省略成员仍取默认值；显式空字符串是合法字符串，业务判断保持原样 ---
197	
198	func TestParseAuditRuleTextOmittedAndExplicitEmpty(t *testing.T) {
199		// 省略 kind/severity/invariant：解析合法，三者取零值 ""。
200		omitted := ruleTextSubmission("[" + ruleObject(`"id":"r1"`, `"version":"1.0.0"`) + "]")
201		aOmit, rulesOmit, _, _, err := ParseAuditInput([]byte(omitted))
202		if err != nil {
203			t.Fatalf("omitted text members must keep their defaults: %v", err)
204		}
205		if rulesOmit[0].Kind != "" || rulesOmit[0].Severity != "" || rulesOmit[0].Invariant != "" {
206			t.Fatalf("omitted members must decode to empty strings: %+v", rulesOmit[0])
207		}
208	
209		// 显式空字符串：同样解析合法，规则定义与省略写法逐字段相同，报告标识一致。
210		explicitEmpty := ruleTextSubmission("[" + ruleObject(
211			`"id":"r1"`, `"kind":""`, `"severity":""`, `"invariant":""`, `"version":"1.0.0"`) + "]")
212		aEmpty, rulesEmpty, _, _, err := ParseAuditInput([]byte(explicitEmpty))
213		if err != nil {
214			t.Fatalf("explicit empty strings must be legal strings: %v", err)
215		}
216		if aEmpty != aOmit || len(rulesEmpty) != 1 || rulesEmpty[0] != rulesOmit[0] {
217			t.Fatalf("omitted and explicit-empty must decode to the same values")
218		}
219		if strictParsedReport(t, omitted).ReportID != strictParsedReport(t, explicitEmpty).ReportID {
220			t.Fatal("omitted and explicit-empty text must share the report id")
221		}
222	
223		// 显式空 id：通过类型关，但仍被既有“rule id is required”业务规则拒绝。
224		emptyID := ruleTextSubmission("[" + ruleObject(`"id":""`, `"version":"1.0.0"`) + "]")
225		a, rules, _, _, err := ParseAuditInput([]byte(emptyID))
226		if err != nil {
227			t.Fatalf("an explicit empty id is a legal string and must parse: %v", err)
228		}
229		if _, err := BuildReport(a, rules, nil, nil); err == nil ||
230			!strings.Contains(err.Error(), "rule id is required") ||
231			strings.Contains(err.Error(), "must be a string") {
232			t.Fatalf("an empty id must keep the required-id business error, got: %v", err)
233		}
234	
235		// 显式空 version：仍是既有必填版本业务错误，不是类型错误。
236		emptyVersion := ruleTextSubmission("[" + ruleObject(`"id":"r1"`, `"version":""`) + "]")
237		a, rules, _, _, err = ParseAuditInput([]byte(emptyVersion))
238		if err != nil {
239			t.Fatalf("an explicit empty version is a legal string and must parse: %v", err)
240		}
241		if _, err := BuildReport(a, rules, nil, nil); err == nil ||
242			!strings.Contains(err.Error(), "version is required") ||
243			strings.Contains(err.Error(), "must be a string") {
244			t.Fatalf("an empty version must keep the required-version business error, got: %v", err)
245		}
246	}
247	
248	// --- 合法字符串逐字保留：中文、换行与前后空格，且产物哈希与报告标识保持原值 ---
249	
250	func TestParseAuditLegalRuleTextPreservedVerbatim(t *testing.T) {
251		id := " 规则 1\n "
252		kind := " 静态\n类型 "
253		severity := " 高 "
254		invariant := "不变式\nx"
255		version := " v1\n "
256		rule := ruleObject(
257			`"id":`+jsonString(id),
258			`"kind":`+jsonString(kind),
259			`"severity":`+jsonString(severity),
260			`"invariant":`+jsonString(invariant),
261			`"requiresABI":false`,
262			`"version":`+jsonString(version),
263		)
264		in := ruleTextSubmission("["+rule+"]", `"invariants":{`+jsonString(invariant)+`:false}`)
265	
266		artifact, rules, invariants, checks, err := ParseAuditInput([]byte(in))
267		if err != nil {
268			t.Fatalf("a legal submission with CJK/newline/whitespace text must parse: %v", err)
269		}
270		got := rules[0]
271		if got.ID != id || got.Kind != kind || got.Severity != severity ||
272			got.Invariant != invariant || got.Version != version {
273			t.Fatalf("rule text must be preserved verbatim:\n%+v", got)
274		}
275		if invariants[invariant] != false {
276			t.Fatalf("the invariant conclusion must bind to the verbatim name: %+v", invariants)
277		}
278		if ArtifactHash(artifact) != ArtifactHash(strictTestArtifact()) {
279			t.Fatal("legal text must keep the original artifact hash")
280		}
281	
282		// 与同样字段直接构造的 Go 值构建出的报告共享标识，缺陷证据逐字保留。
283		directArtifact := strictTestArtifact()
284		directRules := []Rule{{ID: id, Kind: kind, Severity: severity, Invariant: invariant, Version: version}}
285		want, err := BuildReport(directArtifact, directRules, map[string]bool{invariant: false}, nil)
286		if err != nil {
287			t.Fatal(err)
288		}
289		report, err := BuildReport(artifact, rules, invariants, checks)
290		if err != nil {
291			t.Fatalf("a legal submission must build a report: %v", err)
292		}
293		if report.ReportID != want.ReportID {
294			t.Fatalf("report id must keep its existing value:\n got %s\nwant %s", report.ReportID, want.ReportID)
295		}
296		if len(report.Findings) != 1 {
297			t.Fatalf("inv=false must produce exactly one finding, got %+v", report.Findings)
298		}
299		f := report.Findings[0]
300		if f.RuleID != id || f.Severity != severity || f.Invariant != invariant || f.Version != version {
301			t.Fatalf("finding must bind the verbatim rule text: %+v", f)
302		}
303		if f.Evidence != invariantEvidence(invariant) {
304			t.Fatalf("evidence must be the verbatim invariant text, got %q", f.Evidence)
305		}
306	}
307	
308	// --- 大小写变体、带空格名称与未知成员是扩展信息：其中的 null 不触发错误，
309	// 合法字符串也不能补上缺失字段或挽救非法正式字段（无论写在前还是后） ---
310	
311	func TestParseAuditRuleTextVariantsIgnored(t *testing.T) {
312		// 正式 kind 省略，变体携带 null 或字符串：只是扩展信息，kind 仍取零值，
313		// 报告标识与不含任何变体的提交一致。
314		plain := ruleTextSubmission("[" + ruleObject(`"id":"r1"`, `"version":"1.0.0"`) + "]")
315		for _, ext := range []string{
316			`"Kind":null`,
317			`" kind ":null`,
318			`"mystery":null`,
319			`"Kind":"symbolic"`,
320			`" kind ":" static "`,
321		} {
322			rule := ruleObject(`"id":"r1"`, `"version":"1.0.0"`, ext)
323			got := strictParsedReport(t, ruleTextSubmission("["+rule+"]"))
324			if got.Rules[0].Kind != "" {
325				t.Fatalf("extension member %s must not supply a missing formal kind: %+v", ext, got.Rules[0])
326			}
327			if got.ReportID != strictParsedReport(t, plain).ReportID {
328				t.Fatalf("extension member %s changed the report id", ext)
329			}
330		}
331	
332		// 正式 kind 为 null，旁边的变体携带合法字符串（位于其前或其后）都不能挽救。
333		for _, pos := range []string{"before", "after"} {
334			t.Run(pos, func(t *testing.T) {
335				var members []string
336				if pos == "before" {
337					members = []string{`"id":"r1"`, `"Kind":"static"`, `"kind":null`, `"version":"1.0.0"`}
338				} else {
339					members = []string{`"id":"r1"`, `"kind":null`, `" kind ":"static"`, `"version":"1.0.0"`}
340				}
341				expectInvalidRuleText(t, ruleTextSubmission("["+ruleObject(members...)+"]"),
342					"rules[0]", "r1", "kind")
343			})
344		}
345	}
346	
347	// --- Unicode 转义写出的正式名称遵守同一字符串规则 ---
348	
349	func TestParseAuditEscapedRuleTextNameFollowsSameRule(t *testing.T) {
350		// "kind" 的首字母 k 的码位是 0x6b：转义写出后解码仍是正式 kind，null 拒绝。
351		escName := "\\" + "u006b" + "ind"
352		rule := ruleObject(`"id":"r1"`, `"`+escName+`":null`, `"version":"1.0.0"`)
353		in := ruleTextSubmission("[" + rule + "]")
354		if !strings.Contains(in, `\`+"u006bind") {
355			t.Fatalf("test setup must carry the JSON escape, got %s", in)
356		}
357		expectInvalidRuleText(t, in, "rules[0]", "r1", "kind")
358	
359		// 转义写法携带合法字符串时，与直接书写解析到同一规则、同一报告标识。
360		escaped := ruleTextSubmission("[" + ruleObject(
361			`"id":"r1"`, `"`+escName+`":"static"`, `"severity":"high"`,
362			`"invariant":"inv"`, `"requiresABI":false`, `"version":"1.0.0"`) + "]")
363		plainLegal := ruleTextSubmission("[" + artifactTextRule + "]")
364		if strictParsedReport(t, escaped).ReportID != strictParsedReport(t, plainLegal).ReportID {
365			t.Fatal("escaped and plain spellings of a legal string must share the report id")
366		}
367	}
