213				}
214	
215				ruleC := conflictReportRule(t, report, "rule-c")
216				fC, hasFC := conflictFindingFor(t, report, "rule-c")
217				if !value {
218					if ruleC.Status != StatusDefect {
219						t.Fatalf("solo-inv=false 必须使 rule-c 发现缺陷: %+v", ruleC)
220					}
221					if !hasFC {
222						t.Fatalf("rule-c 的布尔缺陷必须产生 finding: %+v", report.Findings)
223					}
