225						t.Fatalf("布尔结论的证据沿用现有表达，got %q", fC.Evidence)
226					}
227					if fC.Version != "3.0.0" || fC.ArtifactHash != hash || fC.Severity != "medium" {
228						t.Fatalf("布尔缺陷必须绑定 rule-c 自身的版本与产物哈希: %+v", fC)
229					}
