232					}
233				} else {
234					if ruleC.Status != StatusPass {
235						t.Fatalf("solo-inv=true 必须使 rule-c 通过: %+v", ruleC)
236					}
237					if hasFC {
238						t.Fatalf("通过的 rule-c 不得有 finding: %+v", fC)
239					}
240					if len(report.Findings) != 1 {
241						t.Fatalf("只有 rule-a 一条缺陷，got %+v", report.Findings)
242					}
243				}
244			})
245		}
246	}
