248	// --- 名称按原文精确匹配：大小写不同或带前后空格的名称不会自动合并，
249	// 既不与共享名下的记录冲突，也不作用于任何规则 ---
250	
251	func TestBuildReportConflictInvariantNameMatchingIsExact(t *testing.T) {
252		hash := ArtifactHash(strictTestArtifact())
253		rec := conflictCheckJSON(hash, "rule-a", "1.0.0", StatusPass, "")
254		plain := ruleTextSubmission(conflictRulesJSON, `"checks":[`+rec+`]`)
255		want := strictParsedReport(t, plain)
256	
257		in := ruleTextSubmission(conflictRulesJSON,
258			`"invariants":{"Shared-Inv":false," shared-inv ":false}`,
259			`"checks":[`+rec+`]`)
260		got := strictParsedReport(t, in)
261	
262		if got.ReportID != want.ReportID {
263			t.Fatalf("大小写/空格变体不得改变报告标识:\n got %s\nwant %s", got.ReportID, want.ReportID)
264		}
265		if r := conflictReportRule(t, got, "rule-a"); r.Status != StatusPass {
266			t.Fatalf("rule-a 的结论必须来自检查记录: %+v", r)
267		}
268		for _, id := range []string{"rule-b", "rule-c"} {
269			if r := conflictReportRule(t, got, id); r.Status != StatusUnchecked {
270				t.Fatalf("变体名布尔值不得作用于 %s: %+v", id, r)
271			}
272		}
273		if len(got.Findings) != 0 {
274			t.Fatalf("变体名布尔值不得产生缺陷: %+v", got.Findings)
275		}
276	}
