1	// Package contractsentinel: strict detection of repeated JSON object members.
2	package contractsentinel
3	
4	import (
5		"encoding/json"
6		"fmt"
7		"strconv"
8	)
9	
10	// duplicateMemberError records the repeated member name and the path of the
11	// object containing it. The path is schema-free; duplicateMemberMessage turns
12	// it into a user-facing message that names the rule id or check ruleId when
13	// the object is a rules/checks array entry.
14	type duplicateMemberError struct {
15		member string
16		path   []jsonPathStep
17	}
18	
19	func (e *duplicateMemberError) Error() string {
20		return "duplicate JSON member " + strconv.Quote(e.member)
21	}
22	
23	// findDuplicateJSONMember scans data structurally and returns the first JSON
24	// object that repeats a member name. encoding/json keeps only the last value
25	// for a repeated key, so without this scan an invariants object writing the
26	// same invariant as false then true would import just the pass, and null
27	// then false would smuggle a defect past the non-boolean rejection.
28	//
29	// Member names are compared after JSON string decoding: "inv" written
30	// literally and the same name written with a Unicode escape collide.
31	// Comparison is case sensitive and never trims whitespace. Every object is
32	// checked, including the top-level object, nested objects and every array
33	// element; identical member names in different objects are normal. String
34	// values are consumed atomically, so text inside a string that looks like
35	// JSON is ordinary content and is never scanned.
36	//
37	// The structural walk itself — which values are objects or arrays, how deep
38	// they nest and which path locates each of them — is shared with the
39	// character-legality check in walkJSONTokens, so the two checks can never
40	// drift apart on how nested input is traversed. This check only adds its own
41	// per-object bookkeeping of the member names already seen.
42	//
43	// Malformed JSON yields nil here; json.Unmarshal remains the single source
44	// of syntax errors and runs right after this scan.
45	func findDuplicateJSONMember(data []byte) *duplicateMemberError {
46		var dup *duplicateMemberError
47		// seenStack holds the member names seen so far in each open object,
48		// innermost object last; enterObject and exitObject keep it in step with
49		// the walk.
50		var seenStack []map[string]bool
51		walkJSONTokens(data, jsonWalkHooks{
52			enterObject: func(path []jsonPathStep) {
53				seenStack = append(seenStack, make(map[string]bool))
54			},
55			exitObject: func(path []jsonPathStep) {
56				seenStack = seenStack[:len(seenStack)-1]
57			},
58			memberName: func(path []jsonPathStep, name string, start, end int) bool {
59				seen := seenStack[len(seenStack)-1]
60				if seen[name] {
61					// path locates the containing object, not the repeated member;
62					// take a copy so later walk events cannot overwrite the
63					// retained path.
64					dup = &duplicateMemberError{member: name, path: append([]jsonPathStep(nil), path...)}
65					return true
66				}
67				seen[name] = true
68				return false
69			},
70		})
71		return dup
72	}
73	
74	// duplicateMemberMessage renders the user-facing error: it states that a
75	// member is duplicated, quotes the decoded member name, and locates the
76	// object. Rules and check records are named by their id / ruleId so the user
77	// can tell which entry is wrong.
78	func duplicateMemberMessage(data []byte, dup *duplicateMemberError) string {
79		return "duplicate JSON member " + strconv.Quote(dup.member) + " in " + locateDupObject(data, dup.path)
80	}
81	
82	// locateDupObject describes the object that contains the repeated member.
83	func locateDupObject(data []byte, path []jsonPathStep) string {
84		if len(path) == 0 {
85			return "the top-level object"
86		}
87		head := path[0]
88		switch head.key {
89		case "artifact":
90			if len(path) == 1 {
91				return "the artifact object"
92			}
93			return "the artifact object (" + renderJSONPath(path[1:]) + ")"
94		case "invariants":
95			if len(path) == 1 {
96				return "the invariants object"
97			}
98			return "the invariants object (" + renderJSONPath(path[1:]) + ")"
99		case "rules", "checks", "findings":
100			// The entry itself is the second path step (an array index).
101			if len(path) >= 2 && path[1].index >= 0 {
102				loc := fmt.Sprintf("%s[%d]", head.key, path[1].index) + renderJSONPath(path[2:])
103				if id := arrayEntryID(data, head.key, path[1].index); id != "" {
104					switch head.key {
105					case "rules":
106						return fmt.Sprintf("rule %q (%s)", id, loc)
107					case "checks":
108						return fmt.Sprintf("check record for rule %q (%s)", id, loc)
109					default:
110						return fmt.Sprintf("finding for rule %q (%s)", id, loc)
111					}
112				}
113				switch head.key {
114				case "rules":
115					return "rule entry " + loc
116				case "checks":
117					return "check record " + loc
118				default:
119					return "finding entry " + loc
120				}
121			}
122		}
123		return "object at " + renderJSONPath(path)
124	}
125	
126	// arrayEntryID extracts the identifying field of one rules/checks/findings
127	// array element. Rules carry their own id; check and finding records name the
128	// rule via ruleId. The unmarshal is last-key-wins for repeated members, which
129	// is fine here: identification only needs some id carried by the offending
130	// entry, and the index already makes it unambiguous.
131	func arrayEntryID(data []byte, field string, index int) string {
132		var root map[string]any
133		if err := json.Unmarshal(data, &root); err != nil {
134			return ""
135		}
136		arr, ok := root[field].([]any)
137		if !ok || index < 0 || index >= len(arr) {
138			return ""
139		}
140		obj, ok := arr[index].(map[string]any)
141		if !ok {
142			return ""
143		}
144		idKey := "ruleId"
145		if field == "rules" {
146			idKey = "id"
147		}
148		if v, ok := obj[idKey].(string); ok {
149			return v
150		}
151		return ""
152	}
153

