	}
	if _, err := os.Stat(store); !os.IsNotExist(err) {
		t.Fatalf("failure must not create the report store: %v", err)
	}
}

// 目录中已有报告时，一次失败的提交必须保持原有内容原样不变。
func TestCLIAuditNullInvariantKeepsExistingReports(t *testing.T) {
	bin := auditBinary(t)
	work := t.TempDir()
