	// 第一条合法、第二条非法：报 checks[1] 与 r2。
	good := checkNoteRecord(hash, "r1", "1.0.0", StatusPass, "", false)
	bad := checkNoteRecord(hash, "r2", "1.0.0", StatusPass, "null", true)
	// 两条记录引用同一条规则定义不可行（重复记录会触发业务错误），因此用
