	rec := checkNoteRecord(hash, "", "1.0.0", StatusPass, "null", true)
	rec = strings.Replace(rec, `"ruleId":""`, `"ruleId":null`, 1)
	expectInvalidCheckNote(t, checkNoteSubmission(rec), "checks[0]", "")
